def create_dicke_state_adaptive(num_qubits: int, num_excitations: int):
    data = _BONUS_NATIVE.get((num_qubits, num_excitations))
    if data is None:
        return _fallback_create_dicke_state_adaptive(num_qubits, num_excitations)
    coordinates, layers = data
    qubits = [cirq.GridQubit(r, c) for r, c in coordinates]
    moments = []
    for layer in layers:
        operations = []
        for entry in layer:
            if len(entry) == 2:
                i, j = entry
                operations.append(cirq.CZ(qubits[i], qubits[j]))
            else:
                i, x, z, a = entry
                operations.append(cirq.PhasedXZGate(x_exponent=x, z_exponent=z, axis_phase_exponent=a).on(qubits[i]))
        moments.append(cirq.Moment(operations))
    return cirq.Circuit(moments), set(qubits)
